import json,hashlib,statistics
from pathlib import Path
P=Path(__file__).resolve().parent;D=P/'confirmation_cpu_01'
s=json.loads((D/'settings.json').read_text());rows=json.loads((D/'rows.json').read_text());b=json.loads((D/'batches.json').read_text())
assert s['complete'] and s['production_hashes']==s['production_hashes_after']
for f,h in s['source_hashes'].items():assert hashlib.sha256((P/f).read_bytes()).hexdigest()==h,f
prior=json.loads((P/'cpu_probe_01/settings.json').read_text());assert s['rhs_sha256']==prior['rhs_sha256']
assert s['source_ids']==[0,4,7,14] and s['prefix']==1 and s['tangent_cut']==8 and s['inner_tolerance']==1e-4 and s['inner_maxiter']==8
pairs=[]
for repeat in range(3):
 x={r['method']:r for r in b if r['repeat']==repeat};c=x['compact4_inject'];e=x['exact8_inner']
 pairs.append(dict(repeat=repeat,order=s['orders'][repeat],compact4=c,exact8_inner=e,gain_percent=100*(1-e['batch_complete_seconds']/c['batch_complete_seconds']),observed_wall_gain_percent=100*(1-e['observed_batch_wall_seconds']/c['observed_batch_wall_seconds']),net_saved_seconds=c['batch_complete_seconds']-e['batch_complete_seconds']))
by={m:[x['batch_complete_seconds'] for x in b if x['method']==m] for m in ['compact4_inject','exact8_inner']}
report=dict(complete=True,scope=s['scope'],pairs=pairs,median_complete_seconds={m:statistics.median(v) for m,v in by.items()},median_paired_gain_percent=statistics.median([p['gain_percent'] for p in pairs]),minimum_paired_gain_percent=min(p['gain_percent'] for p in pairs),maximum_paired_gain_percent=max(p['gain_percent'] for p in pairs),median_observed_wall_gain_percent=statistics.median(p['observed_wall_gain_percent'] for p in pairs),attempts=len(rows),failures=sum(not x['accepted'] for x in rows),reference_attempts=len(json.loads((D/'reference_checks.json').read_text())),reference_research_seconds=s['reference_research_seconds'],wall_seconds=s['wall_seconds'],max_original_residual=max(x['true_residual'] for x in rows),max_evaluated_bound=max(x['evaluated_relative_bound'] for x in rows),max_field_difference=max(x['relative_field_difference'] for x in rows),exact_inner_residuals=[v['true_residual'] for x in rows if x['method']=='exact8_inner' for v in x['inner_records']],exact_inner_failures=sum(v['failed'] for x in rows if x['method']=='exact8_inner' for v in x['inner_records']),production_hashes_unchanged=True,source_arrays_unchanged=True)
(P/'confirmation_analysis.json').write_text(json.dumps(report,indent=2)+'\n')
lines=['# Same-instance CPU confirmation','','All parameters, material and four source arrays were frozen. Six candidate batches rebuilt and paid physical/acceptance setup, TSA64 cache and method factor; paired method order was reversed in the middle repetition. CPU0, one thread, no GPU.','','| Pair | Order | compact4 setup | exact8 setup | compact4 total | exact8 total | Gain |','|---:|---|---:|---:|---:|---:|---:|']
for x in pairs:
 c=x['compact4'];e=x['exact8_inner'];lines.append(f"| {x['repeat']} | {' then '.join(x['order'])} | {c['setup_seconds']:.3f}s | {e['setup_seconds']:.3f}s | {c['batch_complete_seconds']:.3f}s | {e['batch_complete_seconds']:.3f}s | {x['gain_percent']:.2f}% |")
lines+=['',f"Median paired gain: {report['median_paired_gain_percent']:.2f}% (range {report['minimum_paired_gain_percent']:.2f}% to {report['maximum_paired_gain_percent']:.2f}%). No confidence interval is asserted from three pairs.",'',f"Observed full batch wall, including small untimed-in-components loop/norm work, has median paired gain {report['median_observed_wall_gain_percent']:.2f}%; those raw wall times are also retained.",'','## Mechanism and acceptance','']
for m in by:lines.append(m+': outer calls '+str([x['calls'] for x in b if x['method']==m])+'. Inner calls '+str([x['inner_calls'] for x in b if x['method']==m])+'.')
lines += ['',f"All {report['attempts']} candidate outer solves passed; exact inner failures: {report['exact_inner_failures']}. Worst original residual {report['max_original_residual']:.6g}, evaluated relative-error bound {report['max_evaluated_bound']:.6g}, paired field difference {report['max_field_difference']:.6g}. Source hashes and production hashes are unchanged.",'',f"Four ordinary native solves were computed only for paired field checks, using the same1e-5 outer threshold. Their research cost is separately recorded: {report['reference_research_seconds']:.3f}s. Total confirmation main wall: {report['wall_seconds']:.3f}s. They are not candidate inputs or accurate new teachers.",'','## Bounded decision','','If every paired gain is positive with invariant calls/acceptance, clear the same-instance CPU timing gate only. Material transfer, GPU economics, single-RHS latency and production remain unproven. Do not enlarge the RHS count or relax tolerance.','', 'Next material gate must be declared before looking: a proposed adverse direction is doubling only the original inclusion amplitude from3 to6, leaving its position, width, source arrays and all numerical parameters unchanged. This is an unscreened physical perturbation, not a statistically representative holdout. GPU work needs an exclusive coordinated slot.','']
(P/'CONFIRMATION_REPORT.md').write_text('\n'.join(lines));print(json.dumps(report,indent=2))
